/// A structured, translatable error (see `docs/architecture.md` §7.7).
class ApiError implements FrbException {
  /// Stable code, the translation key.
  final String code;

  /// Named arguments for the translation.
  final Map<String, String> args;

  /// English fallback.
  final String text;

  const ApiError({required this.code, required this.args, required this.text});

  @override
  int get hashCode => code.hashCode ^ args.hashCode ^ text.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ApiError &&
          runtimeType == other.runtimeType &&
          code == other.code &&
          args == other.args &&
          text == other.text;
}

