/// State of the cloth simulation, for the UI.
class SimStatus {
  /// A garment is loaded (placed around the body).
  final bool loaded;
  final bool running;

  /// Simulated time (s).
  final double timeS;

  /// Wall time of the last solver step (ms).
  final double stepMs;
  final int particles;

  /// Largest opening of a seam (mm).
  final double maxSeamGapMm;

  /// Where the solver runs: `cpu` or `gpu`.
  final String backend;

  /// The avatar's motion chosen last (`walk`, `turn`, `raise_arms`,
  /// `idle`), if
  /// any: playing, or next once the body is back at rest.
  final String? motion;

  const SimStatus({
    required this.loaded,
    required this.running,
    required this.timeS,
    required this.stepMs,
    required this.particles,
    required this.maxSeamGapMm,
    required this.backend,
    this.motion,
  });

  @override
  int get hashCode =>
      loaded.hashCode ^
      running.hashCode ^
      timeS.hashCode ^
      stepMs.hashCode ^
      particles.hashCode ^
      maxSeamGapMm.hashCode ^
      backend.hashCode ^
      motion.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is SimStatus &&
          runtimeType == other.runtimeType &&
          loaded == other.loaded &&
          running == other.running &&
          timeS == other.timeS &&
          stepMs == other.stepMs &&
          particles == other.particles &&
          maxSeamGapMm == other.maxSeamGapMm &&
          backend == other.backend &&
          motion == other.motion;
}

/// Where a pointer lands on the board, and why: `kind` is `point`,
/// `midpoint`, `edge`, `guide`, `axis`, `horizontal`, `vertical` or
/// `free`; for `horizontal` and `vertical`, `from` is the point it is
/// level with (`[x, y]` mm).
class Snap {
  final double xMm;
  final double yMm;
  final String kind;
  final Float64List? from;

  const Snap({
    required this.xMm,
