      heightCm.hashCode ^
      garmentCm.hashCode ^
      closed.hashCode ^
      bodyCm.hashCode ^
      easeCm.hashCode ^
      gapMm.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is TapeReading &&
          runtimeType == other.runtimeType &&
          heightCm == other.heightCm &&
          garmentCm == other.garmentCm &&
          closed == other.closed &&
          bodyCm == other.bodyCm &&
          easeCm == other.easeCm &&
          gapMm == other.gapMm;
}

